  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- postpartum week 9: Iron, restoring what birth drew on
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   9,
   NULL,
   'Phase 2 of 6 — Finding rhythm',
   'Iron, restoring what birth drew on',
   '"Replenishing takes longer than the blood loss did."',
   'Birth — even a straightforward one — involves real blood loss, and many mothers start these postpartum weeks with lower iron stores than they had before pregnancy. Iron helps your body make hemoglobin, the part of your blood that carries oxygen throughout your body and supports the physical work of recovery. If you are breastfeeding or expressing milk: Breastfeeding itself doesn''t raise your iron needs the way pregnancy did. In fact, once your periods pause — as they commonly do with frequent breastfeeding — your day-to-day iron target is typically lower than it was before pregnancy, since you''re no longer losing iron through monthly bleeding. This week isn''t about eating ''extra'' iron indefinitely; it''s about replenishing what birth may have drawn down, then settling into an ordinary, sustainable pattern. If you are not breastfeeding: If you''re not breastfeeding, your periods may return sooner, which can mean regular iron losses resume too. Replenishing after birth still matters in the same way — the meals this week are equally relevant to you. Postpartum anemia is common — affecting roughly a fifth to half of mothers in various studies — and it isn''t a sign you''ve done anything wrong. It''s simply a real, physical consequence of blood loss at delivery, especially if you lost more blood than usual, were already low on iron during pregnancy, or gave birth to twins or multiples. Worth knowing: Ongoing low iron can show up as persistent tiredness that doesn''t ease with rest, breathlessness on mild exertion, a fast or pounding heartbeat, dizziness, pale skin or nail beds, or low mood — these are worth mentioning at your postpartum check-up rather than assuming they''re just ''normal'' new-parent exhaustion. A simple blood test can tell you whether iron is actually part of the picture. Heme and nonheme iron: Iron from meat, poultry, and fish (called heme iron) is absorbed more easily by your body than the iron in plant foods, dal, and whole grains (called nonheme iron). Both genuinely count. Leafy greens like spinach and methi, legumes, whole grains, and millets are real nonheme sources, even though your body absorbs a smaller share of the iron in them. If you use packaged atta, poha, or another grain product labelled as iron-fortified, it can add a bit more iron on top — but ordinary, unfortified versions of these same staples remain perfectly fine and don''t need to be swapped out. Helping your body absorb more: Vitamin C helps your body absorb nonheme iron — pairing an iron-rich meal with a citrus fruit, tomato, amla, or guava genuinely helps. Tea, coffee, and calcium-rich foods or supplements taken at the very same meal can reduce how much iron you absorb from that meal — spacing them a couple of hours apart from an iron-rich meal or supplement helps, though this isn''t something to be strict or anxious about for ordinary daily eating. A gentle note for this week: If you were taking an iron-folic acid supplement during pregnancy, India''s Anemia Mukt Bharat guidance recommends continuing a daily iron-folic acid tablet for 180 days after birth for many mothers. If anemia has been diagnosed, the treatment dose and duration may be different. Follow the plan given by your care team rather than restarting, stopping, or changing the dose yourself. For adults, the general upper limit for iron is 45 mg a day from food and supplements combined; a clinician may prescribe a higher, supervised dose specifically to treat confirmed anemia. A common side effect of iron supplements is constipation — if that''s already been a focus for you these past weeks, it''s worth mentioning to whoever recommends your dose. If a full plate feels like too much: If keeping up with iron-rich meals every single day feels like a lot right now, that''s genuinely common — a reasonably varied pattern across the week, plus a supplement if your clinician recommends one, matters more than any single ''perfect'' meal. This week''s rhythm: One dependable iron-rich anchor most days — a familiar dal or bean dish, tofu or soy, lean red meat, certain fish, or your supplement if one has been recommended — adds up more than trying to maximize iron at every meal. Each day below offers two options. Some days contrast a meat/fish-based dish and a vegetarian one; other days offer two different dishes that both work either way. Choose whichever suits you today — there''s no ''right'' path between A and B. If you are managing a health condition - Thyroid condition: Iron supplements and multivitamins containing iron can reduce levothyroxine absorption. Take levothyroxine exactly as prescribed and ask your pharmacist how far apart to take it from an iron-containing supplement. Ordinary iron-rich meals do not need complicated scheduling beyond your usual levothyroxine instructions. - Kidney disease: Anemia in kidney disease can have causes beyond diet alone, and how it''s treated (including whether iron is given by mouth or another way) depends on your specific situation. Follow your renal team''s plan rather than self-supplementing. - High blood pressure or previous pre-eclampsia: No specific iron adjustment is needed for blood pressure; continue your prescribed monitoring and medicines as usual. - Diabetes, recent gestational diabetes, or PCOS: Iron doesn''t require special adjustment for a diabetes or PCOS eating plan; iron-rich foods and a supplement, if recommended, are generally fine to include as usual.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "This week is about restocking what birth may have drawn down — not eating iron forever ''extra,'' just replenishing steadily for now. Get help right away if: Bleeding heavy enough to soak through a pad in under an hour, dizziness or fainting, a racing or pounding heart, chest pain, or breathlessness that isn''t explained by activity.", "breakfast_a": "Vegetable daliya with pumpkin seeds and a small orange.", "breakfast_b": "Egg bhurji (yolk included) with toast and unsweetened lime water.", "lunch_a": "Whole-wheat roti with a chana dal and spinach curry.", "lunch_b": "Mutton or lean red meat curry (cooked through) with rice and a tomato-cucumber salad.", "nourishment_break_a": "Roasted chana with a small guava.", "nourishment_break_b": "A handful of roasted peanuts with a small orange.", "dinner_a": "Dal, roti, and a methi (fenugreek leaves) sabzi.", "dinner_b": "Chicken curry (cooked through) with rice.", "still_hungry": "Whatever''s easiest to reach for right now."}, {"day_number": 2, "title": "Heme and nonheme, what''s the difference", "notes": "Meat, poultry, and fish carry iron your body absorbs easily. Dal, greens, and whole grains carry real iron too, just in a form your body absorbs a smaller share of — both genuinely count toward this week.", "breakfast_a": "Vegetable poha with peanuts and a small orange.", "breakfast_b": "Masala omelette (fully cooked, yolk included) with toast.", "lunch_a": "Whole-wheat roti with a rajma (kidney bean) curry.", "lunch_b": "Tofu and vegetable curry with rice.", "nourishment_break_a": "A small bowl of thoroughly cooked sprouted moong with lemon and tomato.", "nourishment_break_b": "A handful of pumpkin seeds with a small orange.", "dinner_a": "Whole-wheat roti with a lobia (black-eyed pea) curry and a tomato side.", "dinner_b": "Soy-chunk and vegetable curry with rice.", "still_hungry": "A familiar snack."}, {"day_number": 3, "title": "Pairing for absorption", "notes": "A squeeze of lemon, a side of tomato, or a piece of citrus fruit alongside a dal or greens-based meal genuinely helps your body take up more of the iron in it. Tea or coffee alongside this meal, or a glass of milk at the very same sitting, can reduce how much of this iron your body actually takes up — having them an hour or two apart from your main iron-rich meal helps, without needing to give either up entirely.", "breakfast_a": "Ragi (finger millet) porridge with a small orange.", "breakfast_b": "Egg-and-vegetable roll (fully cooked) with unsweetened lime water.", "lunch_a": "Whole-wheat roti with a masoor dal and tomato curry.", "lunch_b": "Fish curry made with tomato and tamarind, using a lower-mercury fish, with rice.", "nourishment_break_a": "A small bowl of thoroughly cooked sprouted moong with tomato and a squeeze of lemon.", "nourishment_break_b": "A handful of roasted peanuts with a small guava.", "dinner_a": "Palak (spinach) and paneer curry with soft roti and a tomato side.", "dinner_b": "Bajra roti with a sesame-tempered kala chana curry.", "still_hungry": "A familiar snack."}, {"day_number": 4, "title": "When food alone may not be enough", "notes": "If you lost more blood than usual at delivery, started pregnancy already low on iron, or your postpartum check-up found anemia, food alone often can''t close that gap quickly — a supplement, guided by your care team, does the heavier lifting while food keeps your ordinary intake steady. If this pattern — heavier blood loss, a known low-iron history, or a confirmed anemia result — sounds like your own situation, it''s genuinely worth asking your care team whether a supplement (and what dose) is right for you, rather than waiting to see if food alone catches up.", "breakfast_a": "Vegetable upma with roasted peanuts and a small orange.", "breakfast_b": "Moong-and-vegetable cheela with a tomato-onion side.", "lunch_a": "Whole-wheat roti with a chana-and-spinach curry and a tomato side.", "lunch_b": "Whole cooked moong and vegetable curry with rice.", "nourishment_break_a": "A small bowl of curd with roasted pumpkin seeds.", "nourishment_break_b": "A boiled egg with a small guava.", "dinner_a": "Dal, roti, and a seasonal vegetable sabzi.", "dinner_b": "Fish curry, using a lower-mercury fish, with rice.", "still_hungry": "A familiar snack."}, {"day_number": 5, "title": "Away from home", "notes": "Roasted chana, nuts and seeds, and a piece of citrus fruit travel well and don''t need refrigeration, making them an easy way to keep this week''s focus going on a busy day. Food safety: Keep the sandwich, cheelas, roll, and any dairy refrigerated or in an insulated bag with an ice pack until you need them, and discard anything that''s been sitting out at room temperature for more than about two hours (about one hour in hot weather). Reheat the rajma or curry until steaming hot before eating.", "breakfast_a": "A pre-made egg-and-vegetable sandwich (fully cooked egg) with a small orange, carried in an insulated bag with an ice pack.", "breakfast_b": "Two besan-and-vegetable cheelas, wrapped and kept portable, with a whole orange.", "lunch_a": "A dal-and-vegetable wrap, kept portable, with a tomato side.", "lunch_b": "A pre-made chicken-and-vegetable roll, made with fully cooked chicken, carried in an insulated bag with an ice pack.", "nourishment_break_a": "A handful of roasted pumpkin seeds with a small orange.", "nourishment_break_b": "Roasted chana with a piece of fruit.", "dinner_a": "A reheated rajma-and-rice bowl with a tomato side.", "dinner_b": "A reheated mutton or lean red meat curry with rice.", "still_hungry": "Whatever''s already within reach."}, {"day_number": 6, "title": "Small, steady habits continue", "notes": "Same idea as the past few weeks — one dependable iron-rich anchor, whether that''s a dal you already cook well or your supplement if one''s been recommended, placed at roughly the same point in your day adds up more than any single ''perfect'' meal.", "breakfast_a": "Vegetable daliya with pumpkin seeds and an orange — the same steady start, if that''s what''s working for you.", "breakfast_b": "Egg bhurji (yolk included) with toast.", "lunch_a": "Whole-wheat roti with a chana dal and methi curry.", "lunch_b": "Soy-chunk and vegetable curry with rice and a cucumber side.", "nourishment_break_a": "A small bowl of curd with roasted chana.", "nourishment_break_b": "A handful of pumpkin seeds with a small guava.", "dinner_a": "Palak dal with soft roti.", "dinner_b": "Tofu bhurji with soft roti.", "still_hungry": "A familiar snack."}, {"day_number": 7, "title": "Reflection", "notes": "A quiet week to notice what already felt manageable, and what you''d want to carry into the weeks ahead. Three weeks into Finding rhythm — replenishing your bones, the nutrient that helps you use them, and now the iron that birth asked you to spend, each getting its own turn.", "breakfast_a": "Whichever breakfast felt best this week — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A familiar snack, whatever suits you."}]'::jsonb,
   'Has anything this week made you wonder whether your own iron levels are worth checking — and is that a conversation worth having with your care team?',
   'Next week, we''ll look at another nutrient that plays its own quiet role as you continue finding your rhythm.')
