  looking_ahead = excluded.looking_ahead;

-- postpartum week 17: Vitamin A, for vision, immunity, and healing
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('postpartum',
   17,
   NULL,
   'Phase 3 of 6 — Rebuilding',
   'Vitamin A, for vision, immunity, and healing',
   '"A vitamin your body stores — colour on your plate matters more than any single dose."',
   'Vitamin A supports the vision cells in your eyes (especially seeing in low light), helps your immune system fight off infections, keeps skin and the linings of your gut, lungs, and other tissues healthy, and plays a role in normal cell growth and repair — all relevant while you''re healing and building resistance to the infections that circulate in a house with a newborn. Your daily reference: ICMR-NIN''s confirmed figure for adult women is 840 mcg a day (EAR 390 mcg), though the primary source doesn''t show a separate pregnancy or breastfeeding figure. NIH''s US reference does: 700 mcg a day for other adult women, 770 mcg during pregnancy, and 1,300 mcg while breastfeeding — a substantial increase, since vitamin A is carried into breast milk for your baby. Rather than trying to hit an exact number, aim for a colourful vegetable or fruit, or a dairy source, most days. If you are breastfeeding or expressing milk: If you are breastfeeding or expressing milk, your recommended intake is meaningfully higher than during pregnancy itself, because vitamin A is actively carried into breast milk for your baby in addition to supporting your own tissues. If you are not breastfeeding: If you''re not breastfeeding, vitamin A remains important for healing, immunity, and vision — your daily reference returns to the general adult figure. Where vitamin A comes from: Vitamin A doesn''t split along the usual animal-vs-plant line. Chicken and mutton actually contribute very little of it — this week''s real sources are colourful vegetables and fruits (sweet potato, carrots, spinach, pumpkin, mango, papaya), dairy (milk, curd, paneer), and eggs. If a meal includes chicken, mutton, or fish, it''s the vegetable or fruit alongside it — not the meat itself — that''s carrying this week''s nutrient, so the side matters as much as the main dish. A gentle note for this week: The safe upper limit for vitamin A — 3,000 mcg a day for adults, including while pregnant or breastfeeding — applies only to preformed vitamin A: the kind in animal foods, retinol supplements, and liver. It does not apply to the beta-carotene in colourful vegetables and fruits: ordinary portions of carotenoid-rich vegetables and fruits do not cause the preformed-vitamin-A toxicity associated with retinol supplements or liver, although extremely high carotenoid intake can harmlessly discolour the skin. Liver can contain very large amounts of preformed vitamin A, so it is deliberately excluded from this general chart. If you eat liver or use cod-liver oil, check this with your clinician or dietitian — especially if your multivitamin also contains retinol — rather than trying to calculate a safe combination from this plan. Don''t add a separate high-dose vitamin A supplement beyond your usual prenatal or postnatal multivitamin unless your care team has specifically advised it. This week''s rhythm: A colourful vegetable or fruit, or a dairy source, most meals — sweet potato, carrots, spinach, pumpkin, mango, papaya, milk, curd, or egg — adds up more reliably than trying to concentrate it into one meal. Each day below offers two options, and both are built to carry this week''s nutrient — you don''t need to mix and match to get a genuine vitamin A source. Choose whichever suits you today — there''s no ''right'' path between A and B. If you are managing a health condition - Thyroid condition: There''s no known clinically significant interaction between ordinary vitamin A food intake and thyroid medicines — no special timing or spacing is needed. - Kidney disease: Vitamin A can accumulate when kidney function is reduced, so do not add vitamin A or cod-liver-oil supplements unless your renal team has approved them. Some foods used often this week — including sweet potato, spinach, pumpkin, mango, papaya, milk and curd — may also need adjustment depending on your potassium, phosphorus and fluid plan. Follow your renal team''s food and supplement guidance rather than using this general chart unchanged. - High blood pressure or previous pre-eclampsia: There''s no well-established link between ordinary vitamin A intake and blood pressure or pre-eclampsia risk. Continue your prescribed monitoring and medicines as usual; nothing about this week''s food choices needs to change because of this condition. - Diabetes, recent gestational diabetes, or PCOS: Mango, sweet potato, fruit drinks and sweetened lassi may need particular attention to portion size and pairing. Keep fruit whole where practical, avoid added sugar in lassi, and use the carbohydrate portions already advised for you. Leafy greens, bell peppers, eggs and modest portions of carrots or pumpkin can provide vitamin A with a generally smaller carbohydrate load.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Vitamin A supports vision, immunity, and healing tissue. Both choices below carry a real source through a colourful vegetable, fruit, or dairy food, not just one of them.", "breakfast_a": "Carrot-and-peas poha with a glass of milk.", "breakfast_b": "Masala omelette (two eggs, cooked through) with whole-wheat toast and a side of sautéed spinach.", "lunch_a": "Whole-wheat roti with a pumpkin (kaddu) sabzi and a small bowl of curd.", "lunch_b": "Chicken curry (cooked through) with rice and a sweet-potato sabzi.", "nourishment_break_a": "A ripe mango or papaya, depending on season.", "nourishment_break_b": "A small bowl of curd with diced muskmelon.", "dinner_a": "Dal, roti, an amaranth-leaf (chaulai) sabzi, and a small bowl of curd.", "dinner_b": "Fish curry made with a locally available fish from the lower-mercury category, with rice and a pumpkin sabzi.", "still_hungry": "Whatever''s easiest to reach for right now."}, {"day_number": 2, "title": "A meaningfully higher need while breastfeeding", "notes": "Vitamin A''s recommended intake is higher while breastfeeding than at any other adult life stage — it''s carried into your milk for your baby, on top of supporting your own healing. About your prenatal or postnatal supplement: Vitamin A appears in many prenatal and postnatal multivitamins, sometimes as beta-carotene and sometimes partly as retinol or retinyl esters. Check both the amount and form on the label, and do not add a separate vitamin A or cod-liver-oil supplement solely for this week''s theme.", "breakfast_a": "Vegetable-and-carrot paratha with a small bowl of curd.", "breakfast_b": "Paneer bhurji with whole-wheat toast and a side of sautéed bell peppers.", "lunch_a": "Whole-wheat roti with a mustard-greens (sarson) dal and a small bowl of curd.", "lunch_b": "Mutton curry (cooked through) with rice and a sweet-potato sabzi.", "nourishment_break_a": "Papaya with a small handful of roasted peanuts.", "nourishment_break_b": "A glass of fortified milk (check the label) with a slice of mango on the side.", "dinner_a": "Moong dal, roti, a pumpkin sabzi, and a small bowl of curd.", "dinner_b": "Chicken curry (cooked through) with rice and a carrot-and-bell-pepper sabzi.", "still_hungry": "A familiar snack."}, {"day_number": 3, "title": "Where vitamin A naturally shows up", "notes": "Sweet potato, carrots, dark leafy greens, pumpkin, mango, papaya, dairy, and eggs are quietly doing most of the work this week — worth knowing which ordinary foods are actually carrying it, since it isn''t only a meat-and-fish story.", "breakfast_a": "Sweet-potato-and-vegetable paratha with a small bowl of curd.", "breakfast_b": "Egg bhurji with whole-wheat toast and a side of sautéed spinach or red bell pepper.", "lunch_a": "Whole-wheat roti with a bathua (chenopodium greens) sabzi and a small bowl of dal.", "lunch_b": "A curry made with a locally available fish from the lower-mercury category, with rice and a pumpkin sabzi.", "nourishment_break_a": "Unsweetened mango lassi made with milk and plain yoghurt.", "nourishment_break_b": "Muskmelon (cantaloupe) or another seasonal orange-fleshed fruit.", "dinner_a": "Dal, roti, a spinach-and-corn sabzi, and a small bowl of curd.", "dinner_b": "Chicken curry (cooked through) with rice and a bell-pepper-and-carrot sabzi.", "still_hungry": "A familiar snack."}, {"day_number": 4, "title": "Vision, immunity, and healing: beyond the meal chart", "notes": "Two things worth knowing this week that go beyond the meal chart itself — what vitamin A actually does for your healing body, and a real medicine interaction worth knowing about. About vitamin A and healing: Vitamin A supports the skin and tissue repair involved in healing from birth, whether from a tear, an episiotomy, or a caesarean incision — though it works alongside protein, vitamin C, and zinc, not in place of them, and it isn''t a fast-healing shortcut on its own. About acne or psoriasis medicines: Some prescription retinoids are related to vitamin A, but oral and topical products do not all have the same breastfeeding guidance. Oral isotretinoin is generally not recommended while breastfeeding because adequate safety information is unavailable, and current expert guidance recommends avoiding oral acitretin during breastfeeding. If you are breastfeeding and have been prescribed an oral retinoid, contact the prescriber or pharmacist rather than starting, stopping, or changing it on your own. Topical retinoids have much lower absorption, but should still be discussed with the prescriber and should not be applied on or near the nipple. Make sure the baby''s skin cannot come into contact with any treated area. Avoid adding a separate vitamin A supplement unless the clinician managing the medicine has specifically approved it.", "breakfast_a": "Carrot-and-peas vegetable upma with a glass of milk.", "breakfast_b": "Chicken keema with whole-wheat paratha and a side of spinach.", "lunch_a": "Whole-wheat roti with a pumpkin-and-chana sabzi and a small bowl of curd.", "lunch_b": "Mutton curry (cooked through) with rice and a bell-pepper sabzi.", "nourishment_break_a": "Papaya with a squeeze of lime.", "nourishment_break_b": "A boiled egg with a small red-or-orange-bell-pepper salad.", "dinner_a": "Moong dal, roti, a carrot-and-beans sabzi, and a small bowl of curd.", "dinner_b": "Paneer-and-spinach curry with rice and a cucumber side.", "still_hungry": "A familiar snack."}, {"day_number": 5, "title": "Away from home", "notes": "A carrot stick, a small carton of milk, or a mango are easy, portable ways to keep this week''s focus going on a busy day. Food safety: Keep the sandwiches, wrap, milk, and curd all refrigerated or in an insulated bag with an ice pack, and make sure they stay cold until you actually eat them — discard anything that''s been sitting out at room temperature for more than about two hours (about one hour in hot weather). Reheat the pumpkin-dal curry or mutton-spinach curry until steaming hot before eating.", "breakfast_a": "A pre-made vegetable-and-cheese sandwich with a carrot stick, carried in an insulated bag with an ice pack, kept cold until eaten.", "breakfast_b": "A pre-made boiled-egg-and-spinach sandwich with carrot sticks, carried in an insulated bag with an ice pack, kept cold until eaten.", "lunch_a": "A sweet-potato-and-chickpea wrap, carried in an insulated bag with an ice pack, kept cold until eaten.", "lunch_b": "A pre-made chicken sandwich, made with fully cooked chicken, carried in an insulated bag with an ice pack, kept cold until eaten, with a red-bell-pepper side.", "nourishment_break_a": "A small carton of fortified milk (check the label), kept cold in an insulated bag until drunk.", "nourishment_break_b": "Muskmelon or papaya, kept cold until eaten.", "dinner_a": "A reheated pumpkin-and-dal curry with rice.", "dinner_b": "A reheated mutton-and-spinach curry with rice.", "still_hungry": "Whatever''s already within reach."}, {"day_number": 6, "title": "Small, steady habits continue", "notes": "Same idea as the past few weeks — one colourful vegetable, fruit, or dairy source most meals, placed steadily through your week rather than concentrated into one.", "breakfast_a": "Carrot-and-spinach vegetable daliya with a glass of milk.", "breakfast_b": "Paneer-and-vegetable sandwich with a side of sautéed bell peppers.", "lunch_a": "Whole-wheat roti with an amaranth-leaf (chaulai) dal and a small bowl of curd.", "lunch_b": "A curry made with a locally available fish from the lower-mercury category, with rice and a sweet-potato sabzi.", "nourishment_break_a": "Papaya or mango, depending on season.", "nourishment_break_b": "A small bowl of curd with roasted peanuts.", "dinner_a": "Dal, roti, a bell-pepper sabzi, and a small bowl of curd.", "dinner_b": "Mutton curry (cooked through) with rice and a pumpkin, carrot, or red-bell-pepper sabzi.", "still_hungry": "A familiar snack."}, {"day_number": 7, "title": "Reflection", "notes": "A quiet week to notice what already felt manageable, and what you''d want to carry into the weeks ahead. Still in Rebuilding. A little colour on your plate most days does more for you here than any single perfect meal.", "breakfast_a": "Whichever breakfast felt best this week — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A familiar snack, whatever suits you."}]'::jsonb,
   'Did anything about this week''s foods surprise you — anything already a regular part of your meals?',
   'Next week, we''ll look at another nutrient as you continue rebuilding your own strength.')
